arguments.command:
curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: <TOKEN>" -d '{"query":"query { __type(name: \"Query\") { fields { name args { name type { name kind ofType { name } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__type']['fields']:
    if f['name'] in ('searchIssues','issue','issues'):
        print(f['name'])
        for a in f['args']:
            t=a['type']
            print('  ', a['name'], t['name'] or t['kind'], (t.get('ofType') or {}).get('name') or '')
"

